            Guid id,
            string accountName,
            string? answersJson,
            string? summaryJson,
            string? cardJson,
            string? fastJson,
            string status,
            DateTime updateDate);

        bool DeleteExploration(Guid id, string accountName, DateTime updateDate);
    }
