using chatai.Adapter.Chatai.DTO;

namespace chatai.Adapter.Chatai.DAO
{
    public interface IQaDAO
    {
        /// <summary>
        /// 取得問題描述資料
        /// </summary>
        /// <param name="cid"></param>
        /// <returns></returns>
        DTO.Qa? GetQaData(int id);

        /// <summary>
        /// 取得問題描述
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <returns></returns>
        (int totalCount, IEnumerable<DTO.Qa> data) GetQaList(int pageSize, int page, string question);

        /// <summary>
        /// 取得問題描述
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <param name="cid"></param>
        /// <returns></returns>
        (int totalCount, IEnumerable<DTO.Qa> data) GetQaListForCid(int pageSize, int page, int cid, string question);

        /// <summary>
        /// 取得問題描述For Question
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <param name="question"></param>
        /// <returns></returns>
        (int totalCount, IEnumerable<DTO.Qa> data) GetQaListForQuestion(int pageSize, int page, string[] question);

        /// <summary>
        /// 新增問題描述
        /// </summary>
        /// <param name="qa"></param>
        /// <returns></returns>
        bool AddQa(Qa qa);

        /// <summary>
        /// 修改問題描述
        /// </summary>
        /// <param name="qa"></param>
        /// <returns></returns>
        bool UpdateQa(Qa qa);

    }
}

