2	  <div class="pagination-row">
3	    <div class="pagination-left">
4	      <CPagination v-if="totalCount > 0" aria-label="Page navigation example">
5	        <CPaginationItem class="pagination-item" aria-label="First" :disabled="currentPage === 1"
6	          @click="$emit('changePage', 1)">
7	          <span aria-hidden="true">&laquo;&laquo;</span>
8	        </CPaginationItem>
9	        <CPaginationItem class="pagination-item" aria-label="Previous" :disabled="currentPage === 1"
10	          @click="$emit('changePage', currentPage - 1)">
11	          <span aria-hidden="true">&laquo;</span>
12	        </CPaginationItem>
13	        <CPaginationItem class="pagination-item" v-for="page in paginationRange" :key="page"
14	          :active="page === currentPage" @click="$emit('changePage', page)">
15	          {{ page }}
16	        </CPaginationItem>
17	        <CPaginationItem class="pagination-item" aria-label="Next" :disabled="currentPage === totalPages"
18	          @click="$emit('changePage', currentPage + 1)">
19	          <span aria-hidden="true">&raquo;</span>
20	        </CPaginationItem>
21	        <CPaginationItem class="pagination-item" aria-label="Last" :disabled="currentPage === totalPages"
22	          @click="$emit('changePage', totalPages)">
23	          <span aria-hidden="true">&raquo;&raquo;</span>
24	        </CPaginationItem>
25	      </CPagination>
26	    </div>
27	    <div class="pagination-right" v-if="totalCount > 0">
28	      <CFormLabel>筆數 {{ currentTotal }} / {{ totalCount }}</CFormLabel>
29	    </div>
30	  </div>
31	</template>
