33	<script>
34	export default {
35	  props: {
36	    currentPage: {
37	      type: Number,
38	      required: true,
39	    },
40	    totalCount: {
41	      type: Number,
42	      required: true,
43	    },
44	    pageSize: {
45	      type: Number,
46	      required: true,
47	    },
48	    maxPagesToShow: {
49	      type: Number,
50	      default: 10,
51	    },
52	  },
53	  computed: {
54	    totalPages() {
55	      // 計算總頁數
56	      return Math.ceil(this.totalCount / this.pageSize);
57	    },
58	    paginationRange() {
59	      // 計算當前應顯示的頁碼範圍
60	      const halfRange = Math.floor(this.maxPagesToShow / 2);
61	      let startPage = Math.max(this.currentPage - halfRange, 1);
62	      let endPage = startPage + this.maxPagesToShow - 1;
63	
64	      if (endPage > this.totalPages) {
65	        endPage = this.totalPages;
66	        startPage = Math.max(endPage - this.maxPagesToShow + 1, 1);
67	      }
68	
69	      return Array.from({ length: endPage - startPage + 1 }, (_, i) => startPage + i);
70	    },
71	    currentTotal() {
72	      let result = this.pageSize * this.currentPage
73	      if (result > this.totalCount) {
74	        result = this.totalCount
75	      }
76	      return result;
77	    },
78	  },
79	};
80	</script>
