﻿using AutoMapper;
using Microsoft.Extensions.DependencyInjection;

namespace ntu.Common.Utility.Helper
{
    public static class AutoMapperHelper
    {   
        private static IServiceProvider _serviceProvider;

        public static void Configure(IServiceProvider serviceProvider)
        {
            _serviceProvider = serviceProvider;
        }

        private static IMapper _mapper
        {
            get
            {
                return _serviceProvider.GetRequiredService<IMapper>();
            }
        }

        /// <summary>
        /// 單筆轉換 TSource → TDestination，並可傳遞上下文信息
        /// </summary>
        public static TDestination Map<TSource, TDestination>(TSource source, string lang = "zh")
            where TDestination : new()
        {
            if (source == null)
                return new TDestination();

            return _mapper.Map<TSource, TDestination>(source, options =>
            {
                options.Items["lang"] = lang;
            });
        }

        /// <summary>
        /// 列表轉換 List<TSource> → List<TDestination>，並可傳遞上下文信息
        /// </summary>
        public static List<TDestination> MapList<TSource, TDestination>(List<TSource> sourceList, string lang = "zh")
        {
            if (sourceList == null || !sourceList.Any())
                return new List<TDestination>();

            return _mapper.Map<List<TSource>, List<TDestination>>(sourceList, options =>
            {
                options.Items["lang"] = lang;
            });
        }
    }
}

