import axios from 'axios';
import { isJwtValid, getToken, removeToken } from '@/utils/jwt'
import { baseUrlPath } from '@/utils/env'

axios.interceptors.request.use(config => {
  const token = getToken()
  if (token) {
    if (isJwtValid(token)) {
      config.headers.Authorization = `Bearer ${token}`
    } else {
      removeToken()
      window.location.href = `${baseUrlPath}/pages/login`
      throw new axios.Cancel('JWT expired, redirect to login')
    }
  }
  return config
}, error => Promise.reject(error))

const apiService = {
  async post(url, payload) {
    try {
      const response = await axios.post(url, payload)
      return response.data
    } catch (error) {
      console.error('API Error:', error)
      if (error.response && error.response.data && error.response.data.Message) {
        throw new Error(error.response.data.Message)
      } else {
        throw new Error('發生未知錯誤，請稍後再試')
      }
    }
  },
}

export default apiService;

