    /// <summary>
    /// 後台管理用：依帳號彙總探索紀錄統計（列表第一層），支援帳號模糊搜尋、分頁，依最近活動時間新到舊排序。
    /// </summary>
    internal const string GetExplorationAccountSummaryList = @"SELECT COUNT(*) FROM (SELECT account_name FROM [dbo].[exploration] WHERE is_del=0 AND @account_name GROUP BY account_name) t;
                                            SELECT account_name
                                                ,COUNT(*) AS total_count
                                                ,SUM(CASE WHEN status='completed' THEN 1 ELSE 0 END) AS completed_count
                                                ,MAX(update_date) AS last_update_date
                                                ,AVG(CASE WHEN status='completed' THEN CAST(DATEDIFF(SECOND, create_date, update_date) AS FLOAT) END) AS avg_duration_seconds
                                            FROM [dbo].[exploration]
                                            WHERE is_del=0 AND @account_name
                                            GROUP BY account_name
                                            ORDER BY MAX(update_date) DESC
                                            OFFSET @offset ROWS
                                            FETCH NEXT @page_size ROWS ONLY;";

