namespace ntu.Common.Utility.Response
{
    public class ApiResponse<T>
    {
        public bool Success { get; set; }
        public string Message { get; set; }
        public T? Data { get; set; }
        public int Code { get; set; }

        public ApiResponse(bool success, string message, T? data, int code = 200)
        {
            Success = success;
            Message = message;
            Data = data;
            Code = code;
        }

        public static ApiResponse<T> Ok(T data, string message = "成功")
        {
            return new ApiResponse<T>(true, message, data, 200);
        }

        public static ApiResponse<T> Fail(string message = "發生錯誤", int code = 500)
        {
            return new ApiResponse<T>(false, message, default, code);
        }
    }
}

