10	{
11	    public class ApiResponseMiddleware
12	    {
13	        private readonly RequestDelegate _next;
14	        private readonly ILogger<ApiResponseMiddleware> _logger;
15	
16	        public ApiResponseMiddleware(RequestDelegate next, ILogger<ApiResponseMiddleware> logger)
17	        {
18	            _next = next;
19	            _logger = logger;
20	        }
21	
22	        public async Task InvokeAsync(HttpContext context)
23	        {
24	            if (!context.Request.Path.StartsWithSegments("/api"))
25	            {
26	                await _next(context);
27	                return;
28	            }
29	
30	            var originalBodyStream = context.Response.Body;
31	
32	            using var memoryStream = new MemoryStream();
33	            context.Response.Body = memoryStream;
34	            context.Response.ContentType = "application/json";
35	
36	            try
37	            {
38	                await _next(context);
39	
40	                memoryStream.Seek(0, SeekOrigin.Begin);
41	                var responseBody = await new StreamReader(memoryStream).ReadToEndAsync();
42	
43	                if (IsSuccessStatusCode(context.Response.StatusCode))
44	                {
45	                    object? originalData;
46	                    try
47	                    {
48	                        var node = JsonNode.Parse(responseBody);
49	                        if (node is null)
50	                        {
51	                            originalData = null;
52	                        }
53	                        else
54	                        {
55	                            TrimJsonNodeStrings(node);
56	                            originalData = node;
57	                        }
58	                    }
59	                    catch (JsonException)
60	                    {
61	                        originalData = responseBody; // 如果反序列化失敗，當作純文字處理
62	                    }
63	
64	                    var apiResult = ApiResponse<object>.Ok(originalData);
65	                    var resultJson = JsonSerializer.Serialize(apiResult, GetJsonSerializerOptions());
66	
67	                    context.Response.Body = originalBodyStream;
68	                    context.Response.StatusCode = StatusCodes.Status200OK;
69	                    await context.Response.WriteAsync(resultJson);
70	                }
71	                else if (context.Response.StatusCode == StatusCodes.Status400BadRequest && responseBody.Contains("https://tools.ietf.org/html/"))
72	                {
73	                    var apiErrorResponse = ApiResponse<string>.Fail("請檢查請求參數", StatusCodes.Status400BadRequest);
74	                    var resultJson = JsonSerializer.Serialize(apiErrorResponse);
75	
76	                    context.Response.Body = originalBodyStream;
77	                    context.Response.StatusCode = StatusCodes.Status400BadRequest;
78	                    await context.Response.WriteAsync(resultJson);
79	                }
80	                else
81	                {
82	                    var apiErrorResponse = ApiResponse<string>.Fail(responseBody, context.Response.StatusCode);
83	                    var resultJson = JsonSerializer.Serialize(apiErrorResponse);
84	
85	                    context.Response.Body = originalBodyStream;
86	                    await context.Response.WriteAsync(resultJson);
87	                }
88	            }
89	            catch (CustomException ex)
90	            {
91	                _logger.LogWarning(ex, "Custom exception caught in middleware");
92	
93	                context.Response.Body = originalBodyStream;
94	                context.Response.StatusCode = StatusCodes.Status400BadRequest;
95	
96	                var errorResult = ApiResponse<string>.Fail(ex.DisplayMessage, StatusCodes.Status400BadRequest);
97	                await context.Response.WriteAsync(JsonSerializer.Serialize(errorResult));
98	            }
99	            catch (System.Exception ex)
100	            {
101	                _logger.LogError(ex, "Unhandled exception caught in middleware");
102	
103	                context.Response.Body = originalBodyStream;
104	                context.Response.StatusCode = StatusCodes.Status500InternalServerError;
105	
106	                var errorResponse = ApiResponse<string>.Fail("伺服器內部錯誤", StatusCodes.Status500InternalServerError);
107	                await context.Response.WriteAsync(JsonSerializer.Serialize(errorResponse));
108	            }
109	            finally
110	            {
111	                if (context.Response.Body != originalBodyStream)
112	                {
113	                    context.Response.Body = originalBodyStream;
114	                }
115	            }
116	        }
117	
118	        private static bool IsSuccessStatusCode(int statusCode)
119	        {
120	            return statusCode >= StatusCodes.Status200OK && statusCode < StatusCodes.Status300MultipleChoices;
121	        }
122	
123	        private static void TrimJsonNodeStrings(JsonNode node)
124	        {
125	            if (node is JsonObject obj)
126	            {
127	                foreach (var key in obj.Select(k => k.Key).ToList())
128	                {
129	                    var value = obj[key];
130	                    if (value is null) continue;
131	
132	                    if (TryTrimJsonString(value, out var trimmed))
133	                    {
134	                        obj[key] = trimmed;
135	                        continue;
136	                    }
137	
138	                    TrimJsonNodeStrings(value);
139	                }
140	
141	                return;
142	            }
143	
144	            if (node is JsonArray arr)
145	            {
146	                for (var i = 0; i < arr.Count; i++)
147	                {
148	                    var item = arr[i];
149	                    if (item is null) continue;
150	
151	                    if (TryTrimJsonString(item, out var trimmed))
152	                    {
153	                        arr[i] = trimmed;
154	                        continue;
155	                    }
156	
157	                    TrimJsonNodeStrings(item);
158	                }
159	            }
160	        }
161	
162	        private static bool TryTrimJsonString(JsonNode node, out JsonNode trimmedNode)
163	        {
164	            trimmedNode = node;
165	
166	            if (node is not JsonValue value) return false;
167	            if (!value.TryGetValue<string>(out var str) || str is null) return false;
168	
169	            var trimmed = str.Trim();
170	            if (string.Equals(str, trimmed, StringComparison.Ordinal)) return false;
171	
172	            trimmedNode = JsonValue.Create(trimmed)!;
173	            return true;
174	        }
175	
176	        private static JsonSerializerOptions GetJsonSerializerOptions()
177	        {
178	            return new JsonSerializerOptions
179	            {
180	                DefaultIgnoreCondition = JsonIgnoreCondition.Never
181	            };
182	        }
183	    }
184	}
