using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.Logging;
using ntu.Common.Utility.Exception;
using ntu.Common.Utility.Response;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;

namespace ntu.Common.Utility.Middleware
{
    public class ApiResponseMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<ApiResponseMiddleware> _logger;

        public ApiResponseMiddleware(RequestDelegate next, ILogger<ApiResponseMiddleware> logger)
        {
            _next = next;
            _logger = logger;
        }

        public async Task InvokeAsync(HttpContext context)
        {
            if (!context.Request.Path.StartsWithSegments("/api"))
            {
                await _next(context);
                return;
            }

            var originalBodyStream = context.Response.Body;

            using var memoryStream = new MemoryStream();
            context.Response.Body = memoryStream;
            context.Response.ContentType = "application/json";

            try
            {
                await _next(context);

                memoryStream.Seek(0, SeekOrigin.Begin);
                var responseBody = await new StreamReader(memoryStream).ReadToEndAsync();

                if (IsSuccessStatusCode(context.Response.StatusCode))
                {
                    object? originalData;
                    try
                    {
                        var node = JsonNode.Parse(responseBody);
                        if (node is null)
                        {
                            originalData = null;
                        }
                        else
                        {
                            TrimJsonNodeStrings(node);
                            originalData = node;
                        }
                    }
                    catch (JsonException)
                    {
                        originalData = responseBody; // 如果反序列化失敗，當作純文字處理
                    }

                    var apiResult = ApiResponse<object>.Ok(originalData);
                    var resultJson = JsonSerializer.Serialize(apiResult, GetJsonSerializerOptions());

                    context.Response.Body = originalBodyStream;
                    context.Response.StatusCode = StatusCodes.Status200OK;
                    await context.Response.WriteAsync(resultJson);
                }
                else if (context.Response.StatusCode == StatusCodes.Status400BadRequest && responseBody.Contains("https://tools.ietf.org/html/"))
                {
                    var apiErrorResponse = ApiResponse<string>.Fail("請檢查請求參數", StatusCodes.Status400BadRequest);
                    var resultJson = JsonSerializer.Serialize(apiErrorResponse);

                    context.Response.Body = originalBodyStream;
                    context.Response.StatusCode = StatusCodes.Status400BadRequest;
                    await context.Response.WriteAsync(resultJson);
                }
                else
                {
                    var apiErrorResponse = ApiResponse<string>.Fail(responseBody, context.Response.StatusCode);
                    var resultJson = JsonSerializer.Serialize(apiErrorResponse);

                    context.Response.Body = originalBodyStream;
                    await context.Response.WriteAsync(resultJson);
                }
            }
            catch (CustomException ex)
            {
                _logger.LogWarning(ex, "Custom exception caught in middleware");

                context.Response.Body = originalBodyStream;
                context.Response.StatusCode = StatusCodes.Status400BadRequest;

                var errorResult = ApiResponse<string>.Fail(ex.DisplayMessage, StatusCodes.Status400BadRequest);
                await context.Response.WriteAsync(JsonSerializer.Serialize(errorResult));
            }
            catch (System.Exception ex)
            {
                _logger.LogError(ex, "Unhandled exception caught in middleware");

                context.Response.Body = originalBodyStream;
                context.Response.StatusCode = StatusCodes.Status500InternalServerError;

                var errorResponse = ApiResponse<string>.Fail("伺服器內部錯誤", StatusCodes.Status500InternalServerError);
                await context.Response.WriteAsync(JsonSerializer.Serialize(errorResponse));
            }
            finally
            {
                if (context.Response.Body != originalBodyStream)
                {
                    context.Response.Body = originalBodyStream;
                }
            }
        }

        private static bool IsSuccessStatusCode(int statusCode)
        {
            return statusCode >= StatusCodes.Status200OK && statusCode < StatusCodes.Status300MultipleChoices;
        }

        private static void TrimJsonNodeStrings(JsonNode node)
        {
            if (node is JsonObject obj)
            {
                foreach (var key in obj.Select(k => k.Key).ToList())
                {
                    var value = obj[key];
                    if (value is null) continue;

                    if (TryTrimJsonString(value, out var trimmed))
                    {
                        obj[key] = trimmed;
                        continue;
                    }

                    TrimJsonNodeStrings(value);
                }

                return;
            }

            if (node is JsonArray arr)
            {
                for (var i = 0; i < arr.Count; i++)
                {
                    var item = arr[i];
                    if (item is null) continue;

                    if (TryTrimJsonString(item, out var trimmed))
                    {
                        arr[i] = trimmed;
                        continue;
                    }

                    TrimJsonNodeStrings(item);
                }
            }
        }

        private static bool TryTrimJsonString(JsonNode node, out JsonNode trimmedNode)
        {
            trimmedNode = node;

            if (node is not JsonValue value) return false;
            if (!value.TryGetValue<string>(out var str) || str is null) return false;

            var trimmed = str.Trim();
            if (string.Equals(str, trimmed, StringComparison.Ordinal)) return false;

            trimmedNode = JsonValue.Create(trimmed)!;
            return true;
        }

        private static JsonSerializerOptions GetJsonSerializerOptions()
        {
            return new JsonSerializerOptions
            {
                DefaultIgnoreCondition = JsonIgnoreCondition.Never
            };
        }
    }
