private static List<SqlParameter> GetParametersWithLike(ref string commandText, Dictionary<string, string[]> parametersLike, SqlParameter[] parameters)
{
    List<SqlParameter> allParameters = parameters.ToList();

    if (parametersLike == null || !parametersLike.Any())
        return allParameters;

    foreach (var item in parametersLike)
    {
        // 無值時移除 placeholder，避免 SQL 語法錯誤（條件區塊依賴 has_xxx 參數控制是否生效）
        if (item.Value == null || item.Value.Length <= 0)
        {
            commandText = commandText.Replace($"@{item.Key}", "1=1");
            continue;
        }

        // AND 由 SQL 樣板自行撰寫，此處只輸出 (col LIKE @col0 OR col LIKE @col1)
        string likeClause = string.Join(" OR ", item.Value.Select((v, i) => $"{item.Key} LIKE @{item.Key}{i}"));
        commandText = commandText.Replace($"@{item.Key}", $"({likeClause})");

        allParameters.AddRange(item.Value.Select((v, i) => new SqlParameter($"@{item.Key}{i}", SqlDbType.NVarChar)
        {
            Value = $"%{v}%"
        }));
    }

    return allParameters;

