namespace ntu.Adapter.Core.Common
{
    public class MsSqlProxy
    {
        #region ExecuteScalar

        public static object? ExecuteScalar(IDbConnection connection, IDbTransaction? transaction, CommandType commandType, string commandText, params SqlParameter[] commandParameters)
        {
            Stopwatch stopwatch = new();
            stopwatch.Start();
            object? result = MsSqlHelper.ExecuteScalar(connection, transaction, commandType, commandText, commandParameters);
            stopwatch.Stop();
            return result;
        }

