        private readonly IChataiModule _chataiModule;
        public TestController(ILogger<TestController> logger, AppSettingConfig appSetting, IChataiModule chataiModule)
        {
            _logger = logger;
            _appSetting = appSetting;
            _chataiModule = chataiModule;
        }


#if DEBUG
        [HttpGet]
        public IActionResult Import2()
        {
            // 取得檔案路徑
            var filePath = Path.Combine(Directory.GetCurrentDirectory(), "App_Data", "教務處問答分類.xlsx");
            if (!System.IO.File.Exists(filePath))
            {
                return NotFound($"找不到檔案: {filePath}");
            }

            var result = new List<Dictionary<string, object>>();
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                IWorkbook workbook = new XSSFWorkbook(stream);
                var sheet = workbook.GetSheetAt(0);
                if (sheet == null)
                    return BadRequest("Excel 檔案沒有工作表");

                // 讀取標題列
                var headerRow = sheet.GetRow(0);
                if (headerRow == null)
                    return BadRequest("Excel 檔案沒有標題列");
                var headers = new List<string>();
                for (int i = 0; i < headerRow.LastCellNum; i++)
                {
                    var cell = headerRow.GetCell(i);
                    headers.Add(cell?.ToString() ?? $"Column{i}");
                }

                // 讀取資料列
                for (int i = 1; i <= sheet.LastRowNum; i++)
                {
                    var row = sheet.GetRow(i);
                    if (row == null) continue;
                    var rowData = new Dictionary<string, object>();
                    for (int j = 0; j < headers.Count; j++)
                    {
                        var cell = row.GetCell(j);
                        rowData[headers[j]] = cell?.ToString() ?? string.Empty;
                    }
                    result.Add(rowData);
                }
            }

            var distinctCategories = result
                .Where(x => x.ContainsKey("問題類別"))
                .Select(x => x["問題類別"]?.ToString())
                .Where(x => !string.IsNullOrEmpty(x))
                .Distinct()
                .ToList();

            foreach (var category in distinctCategories)
            {
                _chataiModule.AddQa_category(new chatai.Adapter.Chatai.DTO.Qa_category
                {
                    cname = category!,
                    state = QaEnum.StateSts.start,
                    create_by = "import",
                    update_by = "import",
                    create_date = DateTime.Now,
                    update_date = DateTime.Now
                });
            }

            var qa_categoryList = _chataiModule.GetQa_categoryListAll();

            foreach (var item in result)
            {
                _chataiModule.AddQa(new chatai.Adapter.Chatai.DTO.Qa
                {
                    cid = qa_categoryList.FirstOrDefault(x => x.cname == (item.ContainsKey("問題類別") ? item["問題類別"]?.ToString() ?? string.Empty : string.Empty))?.cid ?? 0,
                    type = QaEnum.TypeSts.organizer,
                    question = item.ContainsKey("問題描述") ? item["問題描述"]?.ToString() ?? string.Empty : string.Empty,
                    answer = item.ContainsKey("承辦單位") ? item["承辦單位"]?.ToString() ?? string.Empty : string.Empty,
                    tel = item.ContainsKey("承辦人分機") ? item["承辦人分機"]?.ToString() ?? string.Empty : string.Empty,
                    email = item.ContainsKey("承辦人email") ? item["承辦人email"]?.ToString() ?? string.Empty : string.Empty,
                    state = QaEnum.StateSts.start,
                    create_by = "import",
                    update_by = "import",
                    create_date = DateTime.Now,
                    update_date = DateTime.Now
                });
            }

            return Ok(new { data = result, distinctCategories });

        }



        [HttpGet]
        public IActionResult Import3()
        {
            // 取得檔案路徑
            var filePath = Path.Combine(Directory.GetCurrentDirectory(), "App_Data", "qa_doc_0106_2.xlsx");
            if (!System.IO.File.Exists(filePath))
            {
                return NotFound($"找不到檔案: {filePath}");
            }

            var result = new List<Dictionary<string, object>>();
            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read))
            {
                IWorkbook workbook = new XSSFWorkbook(stream);
                var sheet = workbook.GetSheetAt(0);
                if (sheet == null)
                    return BadRequest("Excel 檔案沒有工作表");

                // 讀取標題列
                var headerRow = sheet.GetRow(0);
                if (headerRow == null)
                    return BadRequest("Excel 檔案沒有標題列");
                var headers = new List<string>();
                for (int i = 0; i < headerRow.LastCellNum; i++)
                {
                    var cell = headerRow.GetCell(i);
                    headers.Add(cell?.ToString() ?? $"Column{i}");
                }

                // 讀取資料列
                for (int i = 1; i <= sheet.LastRowNum; i++)
                {
                    var row = sheet.GetRow(i);
                    if (row == null) continue;
                    var rowData = new Dictionary<string, object>();
                    for (int j = 0; j < headers.Count; j++)
                    {
                        var cell = row.GetCell(j);
                        rowData[headers[j]] = cell?.ToString() ?? string.Empty;
                    }
                    result.Add(rowData);
                }
            }

            foreach (var item in result)
            {
                _chataiModule.AddQa(new chatai.Adapter.Chatai.DTO.Qa
                {
                    cid = 0,
