    public class TestController : BaseController
    {
        private readonly ILogger<TestController> _logger;
        private readonly AppSettingConfig _appSetting;
        private readonly IChataiModule _chataiModule;
        public TestController(ILogger<TestController> logger, AppSettingConfig appSetting, IChataiModule chataiModule)
        {
            _logger = logger;
            _appSetting = appSetting;
            _chataiModule = chataiModule;
