using chatai.Adapter.Chatai.Common;
using chatai.Adapter.Chatai.DAO;
using chatai.Adapter.Chatai.DAO.Implement;
using LazyProxy.ServiceProvider;
using Microsoft.Extensions.DependencyInjection;

namespace chatai.Adapter.Chatai
{
    public static class DependencyInjection
    {
        public static void Init(IServiceProvider provider)
        {
            DBConfig.Configure(provider);
        }
        public static IServiceCollection AddAdapterChataiServices(this IServiceCollection services)
        {
            services.AddLazyScoped<IQaCategoryDAO, QaCategoryDAO>();
            services.AddLazyScoped<IQaDAO, QaDAO>();
