namespace chatai_admin.Controllers
{
    [Route("api/[controller]/[action]")]
    public class CommonController : BaseApiController
    {
        private readonly AppSettingConfig _appSetting;
        private readonly IChataiModule _chataiModule;

        public CommonController(AppSettingConfig appSetting, IChataiModule chataiModule)
        {
            _appSetting = appSetting;
            _chataiModule = chataiModule;
        }

        [HttpPost]
        public IActionResult GetOptions([FromBody] GetOptionsRequest request)
        {
            var model = new GetOptionsResponse();

            switch (request.type)
            {
                case GetItemsType.qa_category:
                    model.items = this._chataiModule.GetQa_categoryListAll().Select(x => new OptionsItem
                    {
                        value = x.cid.ToString(),
                        label = x.cname
                    }).ToList();
                    break;

                default:
                    break;
            }

            return Ok(model);
        }
    }
}

