using chatai.Adapter.Chatai.Common;
using Microsoft.Data.SqlClient;
using ntu.Adapter.Core.Common;
using System.Data;

namespace chatai.Adapter.Chatai.Command
{
    internal static class AdminPermissionAdapter
    {
        internal static IEnumerable<string> GetModulesForAccount(string accountName)
        {
            SqlParameter[] parameters =
            {
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
            };

            return MsSqlProxy.QueryCollection<DTO.AdminPermission>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.AdminPermission.GetModulesForAccount, parameters)
                .Select(x => x.module_code);
        }

        internal static IEnumerable<DTO.AdminPermission> GetAllGranted()
        {
            return MsSqlProxy.QueryCollection<DTO.AdminPermission>(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.AdminPermission.GetAllGranted);
        }

        /// <summary>
        /// 整批覆蓋：先軟刪該帳號舊的授權列，再依 moduleCodes 逐一新增，不做差異比對。
        /// </summary>
        internal static bool SetModulesForAccount(string accountName, IEnumerable<string> moduleCodes, string operatorAccountName)
        {
            var now = DateTime.Now;

            SqlParameter[] deleteParameters =
            {
                new("account_name", SqlDbType.NVarChar) { Value = accountName },
                new("update_date", SqlDbType.DateTime) { Value = now },
                new("update_by", SqlDbType.NVarChar) { Value = operatorAccountName },
            };
            MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.AdminPermission.DeleteAllForAccount, deleteParameters);

            foreach (var moduleCode in moduleCodes)
            {
                SqlParameter[] insertParameters =
                {
                    new("account_name", SqlDbType.NVarChar) { Value = accountName },
                    new("module_code", SqlDbType.VarChar) { Value = moduleCode },
                    new("create_date", SqlDbType.DateTime) { Value = now },
                    new("create_by", SqlDbType.NVarChar) { Value = operatorAccountName },
                    new("update_date", SqlDbType.DateTime) { Value = now },
                    new("update_by", SqlDbType.NVarChar) { Value = operatorAccountName },
                };
                MsSqlProxy.ExecuteNonQuery(DBConfig.ConnString, CommandType.Text, Common.SqlCommand.AdminPermission.AddPermission, insertParameters);
            }

            return true;
        }
    }
}

