using chatai.Adapter.Chatai.DTO;


namespace chatai.Core.Module.Implement
{
    public class ChataiModule : IChataiModule
    {
        private readonly IQaCategoryDAO _qaCategoryDAO;
        private readonly IQaDAO _qaDAO;
        private readonly IExplorationDAO _explorationDAO;

        public ChataiModule(IQaDAO qaDAO, IQaCategoryDAO qaCategoryDAO, IExplorationDAO explorationDAO)
        {
            _qaDAO = qaDAO;
            _qaCategoryDAO = qaCategoryDAO;
            _explorationDAO = explorationDAO;
        }

        /// <summary>
        /// 取得問題描述資料
        /// </summary>
        /// <param name="id"></param>
        /// <returns></returns>
        public Qa? GetQaData(int id)
        {
            return _qaDAO.GetQaData(id);
        }

        /// <summary>
        /// 取得問題描述
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <returns></returns>
        public (int totalCount, IEnumerable<Qa> data) GetQaList(int pageSize, int page, string question)
        {
            return _qaDAO.GetQaList(pageSize, page, question);
        }

        /// <summary>
        /// 取得問題描述
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <returns></returns>
        public (int totalCount, IEnumerable<Qa> data) GetQaListForCid(int pageSize, int page, int cid, string question)
        {
            return _qaDAO.GetQaListForCid(pageSize, page, cid, question);
        }

        /// <summary>
        /// 取得問題描述For Question
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <param name="question"></param>
        /// <returns></returns>
        public (int totalCount, IEnumerable<Qa> data) GetQaListForQuestion(int pageSize, int page, string[] question)
        {
            return _qaDAO.GetQaListForQuestion(pageSize, page, question);
        }

        /// <summary>
        /// 新增問題描述
        /// </summary>
        /// <param name="qa"></param>
        /// <returns></returns>
        public bool AddQa(Qa qa)
        {
            return _qaDAO.AddQa(qa);
        }

        /// <summary>
        /// 修改問題描述
        /// </summary>
        /// <param name="qa"></param>
        /// <returns></returns>
        public bool UpdateQa(Qa qa)
        {
            return _qaDAO.UpdateQa(qa);
        }

        /// <summary>
        /// 取得問題類別資料
        /// </summary>
        /// <param name="cid"></param>
        /// <returns></returns>
        public Qa_category? GetQa_categoryData(int cid)
        {
            return _qaCategoryDAO.GetQa_categoryData(cid);
        }

        /// <summary>
        /// 取得問題類別
        /// </summary>
        /// <param name="pageSize"></param>
        /// <param name="page"></param>
        /// <returns></returns>
        public (int totalCount, IEnumerable<Qa_category> data) GetQa_categoryList(int pageSize, int page)
        {
            return _qaCategoryDAO.GetQa_categoryList(pageSize, page);
        }

        /// <summary>
        /// 取得所有問題類別
        /// </summary>
        public IEnumerable<Qa_category> GetQa_categoryListAll()
        {
            var result = _qaCategoryDAO.GetQa_categoryList(99999, 1);
