﻿using chatai.Adapter.Chatai.DTO;
using chatai.Core.Config;
using chatai.Core.Models.reponse.Qa;
using chatai.Core.Models.request.Qa;
using chatai.Core.Module;
using chatai_admin.Controllers.Base;
using Microsoft.AspNetCore.Mvc;
using ntu.Common.Utility.Exception;
using ntu.Common.Utility.Helper;
using static chatai.Core.Models.reponse.Qa.SearchResponse;

namespace chatai_admin.Controllers
{
    [Route("api/[controller]/[action]")]
    public class QaController : BaseApiController
    {
        private readonly ILogger<QaController> _logger;
        private readonly AppSettingConfig _appSetting;
        private readonly IChataiModule _chataiModule;
        public QaController(ILogger<QaController> logger, AppSettingConfig appSetting, IChataiModule chataiModule)
        {
            _logger = logger;
            _appSetting = appSetting;
            _chataiModule = chataiModule;
        }

        [HttpPost]
        public IActionResult Search([FromBody] SearchRequest request)
        {
            var model = new SearchResponse();
            (int totalCount, IEnumerable<Qa> data) result;

            if (request.cid > 0)
                result = _chataiModule.GetQaListForCid(request.page_size, request.page, request.cid, request.value);
            else
                result = _chataiModule.GetQaList(request.page_size, request.page, request.value);

            var qa_categoryListAll = _chataiModule.GetQa_categoryListAll();
            var qaResponseList = AutoMapperHelper.MapList<Qa, QaResponse>(result.data.ToList());

            qaResponseList.ForEach(x =>
            {
                x.cname = qa_categoryListAll.FirstOrDefault(y => y.cid == x.cid)?.cname;
            });

            model.Items = qaResponseList;
            model.TotalCount = result.totalCount;

            return Ok(model);
        }

        [HttpPost]
        public IActionResult Save([FromBody] SaveRequest request)
        {
            if (string.IsNullOrEmpty(request.question))
                throw new CustomException("請填寫問題描述");

            var result = new QaResponse();

            if (request.type != chatai.Adapter.Chatai.Enumeration.QaEnum.TypeSts.organizer)
            {
                request.tel = string.Empty;
                request.email = string.Empty;
            }

            if (request.id > 0)
            {
                var qaData = _chataiModule.GetQaData(request.id);

                if (qaData == null)
                    throw new CustomException("找不到該筆資料");

                qaData.cid = request.cid;
                qaData.type = request.type;
                qaData.question = request.question.Trim();
                qaData.answer = request.answer;
                qaData.tel = request.tel;
                qaData.email = request.email;

                qaData.state = request.state;

                qaData.update_by = this.AppJwtUser!.Name;
                qaData.update_date = DateTime.Now;

                _chataiModule.UpdateQa(request);

                result = AutoMapperHelper.Map<Qa, QaResponse>(qaData);
            }
            else
            {
                request.is_del = false;
                request.create_by = this.AppJwtUser!.Name;
                request.update_by = this.AppJwtUser!.Name;
                request.create_date = DateTime.Now;
                request.update_date = DateTime.Now;

                _chataiModule.AddQa(request);

                result = AutoMapperHelper.Map<Qa, QaResponse>(request);
            }

            var qa_categoryListAll = _chataiModule.GetQa_categoryListAll();
            result.cname = qa_categoryListAll.FirstOrDefault(y => y.cid == result.cid)?.cname;

            return Ok(result);
        }

        [HttpPost]
        public IActionResult Delete([FromBody] DeleteRequest request)
        {
            var qaData = _chataiModule.GetQaData(request.id);

            if (qaData == null)
                throw new CustomException("找不到該筆資料");

            qaData.is_del = true;
            qaData.update_by = this.AppJwtUser!.Name;
            qaData.update_date = DateTime.Now;

            var result = _chataiModule.UpdateQa(qaData);

            if (!result)
                throw new CustomException("刪除失敗，請重新再試");

            return Ok();
        }

        [HttpPost]
        public IActionResult UpdateState([FromBody] UpdateStateRequest request)
        {
            var qaData = _chataiModule.GetQaData(request.id);

            if (qaData == null)
                throw new CustomException("找不到該筆資料");

            qaData.state = request.state;
            qaData.update_by = this.AppJwtUser!.Name;
            qaData.update_date = DateTime.Now;

            var result = _chataiModule.UpdateQa(qaData);

            if (!result)
                throw new CustomException("儲存失敗，請重新再試");

            return Ok(result);
        }
    }
}

