﻿using chatai.Core.DTO;
using chatai.Core.Models.reponse.FileManager;
using chatai.Core.Models.request.FileManager;
using chatai_admin.Controllers.Base;
using Microsoft.AspNetCore.Mvc;
using ntu.Common.Utility.Exception;
using ntu.Common.Utility.Helper;

namespace chatai_admin.Controllers
{
    [Route("api/[controller]/[action]")]
    public class FileManagerController : BaseApiController
    {
        private readonly string _baseFolder = Path.Combine(Directory.GetCurrentDirectory(), "App_Data", "doc");

        [HttpPost]
        public IActionResult Tree([FromBody] ListRequest request)
        {
            var folder = string.IsNullOrEmpty(request.subfolder) ? _baseFolder : Path.Combine(_baseFolder, request.subfolder);
            if (!Directory.Exists(folder))
                throw new CustomException("資料夾不存在");

            var tree = GetTree(folder);
            // 強制第一層名稱為 root
            tree.Name = "root";

            var model = AutoMapperHelper.Map<FileNode, ListResponse>(tree);

            return Ok(model);
        }

        [HttpPost]
        public IActionResult CreateFolder([FromBody] CreateFolderRequest request)
        {
            if (string.IsNullOrWhiteSpace(request.FolderName))
                throw new CustomException("請輸入資料夾名稱");

            // 檢查資料夾名稱是否包含不允許的字元
            char[] invalidChars = Path.GetInvalidFileNameChars();
            if (request.FolderName.IndexOfAny(invalidChars) >= 0)
                throw new CustomException("資料夾名稱包含不允許的字元");

            // 計算父資料夾路徑
            var parentPath = string.IsNullOrEmpty(request.ParentFolder)
                ? _baseFolder
                : Path.Combine(_baseFolder, request.ParentFolder);

            if (!Directory.Exists(parentPath))
                Directory.CreateDirectory(parentPath);

            var newFolderPath = Path.Combine(parentPath, request.FolderName);

            if (Directory.Exists(newFolderPath))
                throw new CustomException("資料夾已存在");

            Directory.CreateDirectory(newFolderPath);

            return Ok();
        }

        [HttpPost]
        public async Task<IActionResult> Upload([FromForm] IFormFile file, [FromForm] string? subfolder = null)
        {
            if (file == null || file.Length == 0)
                throw new CustomException("未選擇檔案");

            var allowedExtensions = new[] { ".md", ".pdf", ".xls", ".xlsx", ".csv", ".docx" };
            var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
            if (!allowedExtensions.Contains(ext))
                throw new CustomException("只允許 md、pdf、excel、csv、docx 檔案");

            var folder = string.IsNullOrEmpty(subfolder) ? _baseFolder : Path.Combine(_baseFolder, subfolder);
            if (!Directory.Exists(folder))
                Directory.CreateDirectory(folder);

            var fileName = Path.GetFileNameWithoutExtension(file.FileName);
            var filePath = Path.Combine(folder, file.FileName);
            int count = 1;
            // 自動編號
            while (System.IO.File.Exists(filePath))
            {
                var newFileName = $"{fileName}({count}){ext}";
                filePath = Path.Combine(folder, newFileName);
                count++;
            }

            using (var stream = new FileStream(filePath, FileMode.Create))
            {
                await file.CopyToAsync(stream);
            }
            return Ok();
        }

        [HttpPost]
        public IActionResult DeleteFolder([FromBody] DeleteFolderRequest request)
        {
            if (string.IsNullOrWhiteSpace(request.FolderPath))
                throw new CustomException("未指定資料夾路徑");

            var folder = Path.Combine(_baseFolder, request.FolderPath);
            if (!Directory.Exists(folder))
                throw new CustomException("資料夾不存在");

            // 遞迴刪除資料夾及內容
            Directory.Delete(folder, true);

            return Ok();
        }

        [HttpPost]
        public IActionResult Delete([FromBody] DeleteRequest request)
        {
            if (string.IsNullOrEmpty(request.FileName))
                throw new CustomException("未指定檔案名稱");

            var folder = string.IsNullOrEmpty(request.Subfolder) ? _baseFolder : Path.Combine(_baseFolder, request.Subfolder);
            var filePath = Path.Combine(folder, request.FileName);
            if (!System.IO.File.Exists(filePath))
                throw new CustomException("檔案不存在");

            System.IO.File.Delete(filePath);

            return Ok();
        }

        private FileNode GetTree(string path)
        {
            var node = new FileNode
            {
                Name = Path.GetFileName(path),
                IsFolder = true,
                Children = new List<FileNode>()
            };

            // 資料夾
            foreach (var dir in Directory.GetDirectories(path))
            {
                node.Children.Add(GetTree(dir));
            }
            // 檔案
            foreach (var file in Directory.GetFiles(path))
            {
                node.Children.Add(new FileNode
                {
                    Name = Path.GetFileName(file),
                    IsFolder = false
                });
            }
            return node;
        }
    }
}

