using chatai.Core.Service;
using chatai_admin.Controllers.Base;
using Microsoft.AspNetCore.Mvc;
using ntu.Common.Utility.Exception;

namespace chatai_admin.Controllers
{
    /// <summary>
    /// flowId=6（Gemini File Search RAG）的共用文件管理，跟 QA 管理完全獨立。
    /// 這裡沒有額外的權限標記，是因為全站的 ValidateJWTFilter 已經全域驗證
    /// JWT + AdminUsers 名單，跟其他管理端 controller（例如 QaController）一致。
    /// </summary>
    [Route("api/[controller]/[action]")]
    public class GeminiDocumentController : BaseApiController
    {
        private static readonly string[] AllowedExtensions =
            { ".pdf", ".txt", ".md", ".csv", ".docx", ".jpg", ".jpeg", ".png", ".webp" };

        private const long MaxFileSizeBytes = 50 * 1024 * 1024; // 50MB

        private readonly IGeminiFileSearchService _geminiService;
        private readonly ILogger<GeminiDocumentController> _logger;

        public GeminiDocumentController(IGeminiFileSearchService geminiService, ILogger<GeminiDocumentController> logger)
        {
            _geminiService = geminiService;
            _logger = logger;
        }

        [HttpPost]
        public async Task<IActionResult> List()
        {
            var documents = await _geminiService.ListSharedDocumentsAsync();
            return Ok(documents);
        }

        [HttpPost]
        public async Task<IActionResult> Upload(IFormFile file)
        {
            if (file == null || file.Length == 0)
                throw new CustomException("未選擇檔案");

            if (file.Length > MaxFileSizeBytes)
                throw new CustomException("檔案大小超過 50MB 上限");

            var ext = Path.GetExtension(file.FileName).ToLowerInvariant();
            if (!AllowedExtensions.Contains(ext))
                throw new CustomException($"不支援的檔案格式，只允許：{string.Join(", ", AllowedExtensions)}");

            byte[] fileBytes;
            using (var stream = new MemoryStream())
            {
                await file.CopyToAsync(stream);
                fileBytes = stream.ToArray();
            }

            var mimeType = string.IsNullOrEmpty(file.ContentType) ? "application/octet-stream" : file.ContentType;
            var adminAccount = AppJwtUser?.AccountName ?? "unknown-admin";

            try
            {
                await _geminiService.UploadAndIndexAsync(fileBytes, mimeType, file.FileName, GeminiFileSearchService.SharedUserId);
                _logger.LogInformation("管理端上傳共用文件完成: admin={Admin} file={FileName}", adminAccount, file.FileName);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "管理端上傳共用文件失敗: admin={Admin} file={FileName}", adminAccount, file.FileName);
                throw new CustomException($"上傳或索引失敗：{ex.Message}");
            }

            return Ok(new { message = $"「{file.FileName}」已上傳並完成索引。" });
        }

        public class DeleteRequest
        {
            public string DocumentName { get; set; } = "";
        }

        [HttpPost]
        public async Task<IActionResult> Delete([FromBody] DeleteRequest request)
        {
            if (string.IsNullOrEmpty(request.DocumentName))
                throw new CustomException("缺少文件名稱");

            var adminAccount = AppJwtUser?.AccountName ?? "unknown-admin";

            try
            {
                await _geminiService.DeleteDocumentAsync(request.DocumentName);
                _logger.LogInformation("管理端刪除共用文件: admin={Admin} document={DocumentName}", adminAccount, request.DocumentName);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "管理端刪除共用文件失敗: admin={Admin} document={DocumentName}", adminAccount, request.DocumentName);
                throw new CustomException($"刪除失敗：{ex.Message}");
            }

            return Ok();
        }
    }
}

