namespace chatai_admin.Filter
{
    //[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class)]
    public class ValidateJWTFilter : IActionFilter
    {
        private readonly ILogger<ValidateJWTFilter> _logger;

        private readonly AppSettingConfig _appSettingConfig;

        private readonly IChataiModule _chataiModule;

        //允許Admin帳號種類代碼
        private readonly string[] _requiredAdminAccountType = new string[] { AccountTypeCodeEnum.Staff, AccountTypeCodeEnum.Student, AccountTypeCodeEnum.Faculty };

        public ValidateJWTFilter(ILogger<ValidateJWTFilter> logger, AppSettingConfig appSettingConfig, IChataiModule chataiModule)
        {
            _logger = logger;
            _appSettingConfig = appSettingConfig;
            _chataiModule = chataiModule;
        }

        public void OnActionExecuting(ActionExecutingContext context)
        {
            //if (!IsJWTOnly(context)) return;

            if (IsAllowAnonymous(context)) return;

            if (!context.HttpContext.Request.Headers.TryGetValue("Authorization", out var encryptedSignature))
                throw new CustomException("缺少 Authorization Header.");

            var authToken = encryptedSignature.ToNullString();
            if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer"))
                throw new CustomException("Invalid Authorization Header");

            // 驗證 Token 是否有效
            if (!JWTHelper.ValidateToken(authToken, out var principal))
                throw new CustomException("Authorization驗證失敗");

            var jwtInfo = JWTHelper.GetJwtInfo(authToken);
            if (!_requiredAdminAccountType.Any(x => x == jwtInfo.accountTypeCode) || !_appSettingConfig.AdminUsers!.Any(x => x == jwtInfo.accountName))
                throw new CustomException("沒有權限");

            // 總管理者不受模組權限限制，永遠擁有全部模組。
            if (_appSettingConfig.SuperAdminUsers!.Any(x => x == jwtInfo.accountName))
                return;

            // 沒有標記 [AdminModule] 的 controller（例如 CommonController、HomeController）不受模組限制。
            var moduleAttribute = context.ActionDescriptor.EndpointMetadata.OfType<AdminModuleAttribute>().FirstOrDefault();
            if (moduleAttribute == null)
                return;

            var allowedModules = _chataiModule.GetModulesForAccount(jwtInfo.accountName!);
            if (!allowedModules.Any(x => x == moduleAttribute.ModuleCode))
                throw new CustomException("沒有權限使用此功能");
        }

