        {
            _appSettingConfig = appSettingConfig;
            _chataiModule = chataiModule;
        }

        [HttpPost]
        public IActionResult GetAccounts()
        {
            EnsureSuperAdmin();

            var allAccountModules = _chataiModule.GetAllAccountModules();
            var manageableAccounts = _appSettingConfig.AdminUsers!
                .Except(_appSettingConfig.SuperAdminUsers!)
                .Select(accountName => new AccountModulesResponse
                {
                    account_name = accountName,
                    module_codes = allAccountModules.TryGetValue(accountName, out var modules) ? modules : new List<string>(),
                })
                .ToList();

            return Ok(manageableAccounts);
        }

        [HttpPost]
        public IActionResult Save([FromBody] SaveRequest request)
        {
            EnsureSuperAdmin();

            if (!_appSettingConfig.AdminUsers!.Any(x => x == request.account_name) || _appSettingConfig.SuperAdminUsers!.Any(x => x == request.account_name))
                throw new CustomException("帳號不在可設定的範圍內");

            var result = _chataiModule.SetModulesForAccount(request.account_name, request.module_codes, this.AppJwtUser!.Name);

            if (!result)
                throw new CustomException("儲存失敗，請重新再試");

            return Ok();
        }

        private void EnsureSuperAdmin()
        {
            if (!_appSettingConfig.SuperAdminUsers!.Any(x => x == this.AppJwtUser!.AccountName))
                throw new CustomException("沒有權限");
        }
    }
}

