import { ref } from 'vue'
import { defineStore } from 'pinia'
import { setToken, removeToken } from '@/utils/jwt'
import apiService from '@/services/apiService'

export const useAuthStore = defineStore('auth', () => {
  const isAuthenticated = ref(false)
  const user = ref(null)
  const isSuperAdmin = ref(false)
  const allowedModules = ref([])
  const permissionsLoaded = ref(false)

  function login(userInfo) {
    setToken(userInfo.token)
    isAuthenticated.value = true
    user.value = userInfo
  }

  function logout() {
    removeToken()
    isAuthenticated.value = false
    user.value = null
    isSuperAdmin.value = false
    allowedModules.value = []
    permissionsLoaded.value = false
  }

  function canView(moduleCode) {
    if (isSuperAdmin.value) return true
    if (!moduleCode) return true
    return allowedModules.value.includes(moduleCode)
  }

  async function fetchPermissions() {
    try {
      const data = await apiService.post('api/common/get-my-permissions')
      isSuperAdmin.value = !!data.Data.is_super_admin
      allowedModules.value = data.Data.modules ?? []
    } finally {
      permissionsLoaded.value = true
    }
  }

  // 可根據實際情況擴充
  return {
    isAuthenticated,
    user,
    isSuperAdmin,
    allowedModules,
    permissionsLoaded,
    login,
    logout,
    canView,
    fetchPermissions,
  }
})

