router.beforeEach(async (to, from, next) => {
  const auth = useAuthStore()
  const publicPages = ['/pages/login', '/pages/register', '/pages/404', '/pages/500', '/pages/forbidden']
  // 取得 query string 的 token
  const urlParams = new URLSearchParams(window.location.search)
  const queryToken = urlParams.get('token')
  let token = getToken()
  // 若 query string 有 token 且有效，則自動登入
  if (queryToken && isJwtValid(queryToken)) {
    auth.login({ token: queryToken })
    setToken(queryToken)
    // 清除 token 參數
    window.history.replaceState(null, '', window.location.pathname + window.location.hash)
    token = queryToken
  }
  if (!token || !isJwtValid(token)) {
    auth.logout()
    if (!publicPages.includes(to.path)) {
      return next('/pages/login')
    }
    return next()
  }

  auth.login({ token })

  if (publicPages.includes(to.path)) {
    return next()
  }

  // 重新整理頁面時 store 會重置，權限資料只在 session 內 fetch 一次。
  if (!auth.permissionsLoaded) {
    await auth.fetchPermissions()
  }

  const requiredModule = to.meta?.module
  const superAdminOnly = to.meta?.superAdminOnly
  const allowed = superAdminOnly ? auth.isSuperAdmin : auth.canView(requiredModule)

  if (!allowed) {
    // 真正的防線是後端 ValidateJWTFilter；這裡只是前端縱深防禦，
    // 優先導去使用者自己看得到的第一個模組，而不是直接丟「沒有權限」。
    const fallbackModule = MODULE_ORDER.find((m) => auth.canView(m))
    if (fallbackModule && MODULE_ROUTE[fallbackModule] !== to.path) {
      return next(MODULE_ROUTE[fallbackModule])
    }
    return next('/pages/forbidden')
  }

  next()
})

